<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Online Stopwatch','description'=>'Use a precise browser stopwatch with start, pause, reset and lap controls.','url'=>'https://smarttoolz.in/tools/stopwatch/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">STOPWATCH</span><h1>Online Stopwatch</h1><p>Simple stopwatch with start, pause, reset and lap timing.</p></section><section class="tool-workspace"><div class="tool-panel" style="text-align:center"><div id="time" style="font-size:48px;font-weight:900;font-variant-numeric:tabular-nums">00:00.00</div><button id="start" class="tool-btn">Start</button><button id="lap" class="tool-btn" style="margin-left:8px">Lap</button><button id="reset" class="tool-btn" style="margin-left:8px">Reset</button><ol id="laps" style="text-align:left;margin-top:18px"></ol></div></section></main><script>(()=>{let start=0,elapsed=0,id=null;const t=document.getElementById('time'),fmt=x=>{let m=Math.floor(x/60000),s=Math.floor(x/1000)%60,cs=Math.floor(x/10)%100;return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')+'.'+String(cs).padStart(2,'0')};function tick(){elapsed=Date.now()-start;t.textContent=fmt(elapsed)}document.getElementById('start').onclick=()=>{if(id){clearInterval(id);id=null;event.target.textContent='Resume'}else{start=Date.now()-elapsed;id=setInterval(tick,10);event.target.textContent='Pause'}};document.getElementById('lap').onclick=()=>{if(!id)return;let li=document.createElement('li');li.textContent=fmt(elapsed);document.getElementById('laps').prepend(li)};document.getElementById('reset').onclick=()=>{clearInterval(id);id=null;elapsed=0;t.textContent=fmt(0);document.getElementById('start').textContent='Start';document.getElementById('laps').innerHTML='' }})();</script><?php smarttoolz_tool_page_end(); ?>